#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct ClientHello
{
    std::uint16_t version;
    std::vector<std::uint16_t> cipherSuites;
    std::optional<std::string> serverName;
};

namespace
{
    // Reads big-endian fields from b[at, end). Any read past end clears ok, and every later read fails too.
    struct Reader
    {
        const std::vector<std::uint8_t>& b;
        std::size_t at;
        std::size_t end;
        bool ok{ true };

        bool has(std::size_t n) const { return ok && end - at >= n; }
        bool done() const { return !ok || at == end; }

        std::uint32_t take(std::size_t n)
        {
            if (!has(n)) { ok = false; return 0; }
            std::uint32_t v{ 0 };
            for (std::size_t i{ 0 }; i < n; ++i) v = (v << 8) | b[at++];
            return v;
        }

        void skip(std::size_t n)
        {
            if (!has(n)) { ok = false; return; }
            at += n;
        }

        Reader sub(std::size_t n)
        {
            Reader r{ b, at, at };
            if (!has(n)) { ok = false; r.ok = false; return r; }
            r.end = at + n;
            at += n;
            return r;
        }
    };
}

std::optional<ClientHello> parseClientHello(const std::vector<std::uint8_t>& stream)
{
    Reader r{ stream, 0, stream.size() };
    if (r.take(1) != 22) return std::nullopt;
    r.skip(2);
    Reader record{ r.sub(r.take(2)) };
    if (record.take(1) != 1) return std::nullopt;
    Reader hs{ record.sub(record.take(3)) };
    if (!hs.ok) return std::nullopt;

    ClientHello hello{};
    hello.version = static_cast<std::uint16_t>(hs.take(2));
    hs.skip(32);
    hs.skip(hs.take(1));
    Reader suites{ hs.sub(hs.take(2)) };
    while (!suites.done()) hello.cipherSuites.push_back(static_cast<std::uint16_t>(suites.take(2)));
    hs.skip(hs.take(1));
    if (!suites.ok || !hs.ok) return std::nullopt;
    if (hs.done()) return hello;

    Reader extensions{ hs.sub(hs.take(2)) };
    while (!extensions.done())
    {
        const std::uint32_t type{ extensions.take(2) };
        Reader extension{ extensions.sub(extensions.take(2)) };
        if (!extensions.ok) return std::nullopt;
        if (type != 0) continue;
        Reader list{ extension.sub(extension.take(2)) };
        while (!list.done())
        {
            const std::uint32_t nameType{ list.take(1) };
            Reader name{ list.sub(list.take(2)) };
            if (!list.ok) return std::nullopt;
            if (nameType == 0 && !hello.serverName)
                hello.serverName = std::string(stream.begin() + static_cast<std::ptrdiff_t>(name.at),
                                               stream.begin() + static_cast<std::ptrdiff_t>(name.end));
        }
        if (!list.ok || !extension.ok) return std::nullopt;
    }
    if (!extensions.ok || !hs.ok) return std::nullopt;
    return hello;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
void put16(Bytes& b, std::size_t v) { b.push_back(static_cast<std::uint8_t>(v >> 8)); b.push_back(static_cast<std::uint8_t>(v)); }
Bytes clientHello(const std::string& name, bool withSni) {
    Bytes body;
    put16(body, 0x0303);
    for (int i{ 0 }; i < 32; ++i) body.push_back(static_cast<std::uint8_t>(i));
    body.push_back(32);
    for (int i{ 0 }; i < 32; ++i) body.push_back(0xAA);
    put16(body, 6); put16(body, 0x1301); put16(body, 0x1302); put16(body, 0xC02F);
    body.push_back(1); body.push_back(0);
    Bytes ext;
    put16(ext, 0x000A); put16(ext, 4); put16(ext, 2); put16(ext, 0x001D);
    if (withSni) {
        put16(ext, 0x0000); put16(ext, name.size() + 5); put16(ext, name.size() + 3);
        ext.push_back(0); put16(ext, name.size());
        ext.insert(ext.end(), name.begin(), name.end());
    }
    put16(body, ext.size());
    body.insert(body.end(), ext.begin(), ext.end());
    Bytes record{ 22, 3, 1 };
    put16(record, body.size() + 4);
    record.push_back(1); record.push_back(0); put16(record, body.size());
    record.insert(record.end(), body.begin(), body.end());
    return record;
}
TEST("a ClientHello with a server name") {
    const auto h{ parseClientHello(clientHello("xenon.justloofy.dev", true)) };
    CHECK(h.has_value());
    if (h) {
        CHECK_EQ(h->version, 0x0303);
        CHECK(h->cipherSuites == (std::vector<std::uint16_t>{ 0x1301, 0x1302, 0xC02F }));
        CHECK(h->serverName == std::optional<std::string>{ "xenon.justloofy.dev" });
    }
    Bytes more{ clientHello("example.com", true) };
    more.insert(more.end(), { 23, 3, 3, 0, 1, 0xFF });
    const auto m{ parseClientHello(more) };
    CHECK(m.has_value() && m->serverName == std::optional<std::string>{ "example.com" });
}
TEST("no server name") {
    const auto h{ parseClientHello(clientHello("", false)) };
    CHECK(h.has_value() && !h->serverName && h->cipherSuites.size() == 3);
}
TEST("not a ClientHello") {
    Bytes data{ clientHello("a.b", true) }; data[0] = 23;
    CHECK(!parseClientHello(data).has_value());
    Bytes serverHello{ clientHello("a.b", true) }; serverHello[5] = 2;
    CHECK(!parseClientHello(serverHello).has_value());
    CHECK(!parseClientHello(Bytes{}).has_value());
}
TEST("lengths that lie") {
    const std::string name{ "xenon.justloofy.dev" };
    Bytes cut{ clientHello(name, true) }; cut.pop_back();
    CHECK(!parseClientHello(cut).has_value());
    Bytes extensions{ clientHello(name, true) }; extensions[86] = 0xFF; extensions[87] = 0xFF;
    CHECK(!parseClientHello(extensions).has_value());
    Bytes nameLength{ clientHello(name, true) }; nameLength[nameLength.size() - name.size() - 2] = 1;
    CHECK(!parseClientHello(nameLength).has_value());
    Bytes suites{ clientHello(name, true) }; suites[76] = 0; suites[77] = 5;
    CHECK(!parseClientHello(suites).has_value());
    Bytes message{ clientHello(name, true) }; message[6] = 0x7F;
    CHECK(!parseClientHello(message).has_value());
}

